Definition stk (m : word -> option byte) (lo hi : Z) : Prop :=
  (0 <= lo)%Z /\ (hi <= 2^64)%Z /\
  forall a, (lo <= a < hi)%Z -> wview segs m (wa a) <> None /\ exists b, mrd segs m (wa a) = Some b.

